# -*- coding: utf-8 -*-
SVGS = ['<svg viewBox="0 0 700 240" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="240" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">KUR\'AN-I KERİM\'İN ANA MUHTEVASI VE MERKEZÎ KONUSU: TEVHİD</text>\n  <rect x="230" y="42" width="240" height="50" rx="10" fill="#dcfce7" stroke="#16a34a" stroke-width="2"/>\n  <text x="350" y="64" text-anchor="middle" font-size="12" font-weight="bold" fill="#166534">MERKEZ: KUR\'AN\'DA ALLAH</text>\n  <text x="350" y="82" text-anchor="middle" font-size="9.5" fill="#15803d">Tevhid · Tenzîh (Şûrâ 11) · Esmâ-i Hüsnâ</text>\n  <line x1="150" y1="115" x2="250" y2="92" stroke="#16a34a" stroke-width="1.8"/>\n  <line x1="285" y1="115" x2="320" y2="92" stroke="#16a34a" stroke-width="1.8"/>\n  <line x1="415" y1="115" x2="380" y2="92" stroke="#16a34a" stroke-width="1.8"/>\n  <line x1="550" y1="115" x2="450" y2="92" stroke="#16a34a" stroke-width="1.8"/>\n  <rect x="20" y="115" width="152" height="105" rx="8" fill="#dbeafe" stroke="#2563eb" stroke-width="1.8"/>\n  <text x="96" y="136" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#1e40af">1. İTİKAT (İNANÇ)</text>\n  <text x="96" y="156" text-anchor="middle" font-size="9" fill="#334155">• Tevhid (Ulûhiyyet)</text>\n  <text x="96" y="172" text-anchor="middle" font-size="9" fill="#334155">• Nübüvvet (Peygamberlik)</text>\n  <text x="96" y="188" text-anchor="middle" font-size="9" fill="#334155">• Meâd (Ahiret hayatı)</text>\n  <rect x="186" y="115" width="152" height="105" rx="8" fill="#fef3c7" stroke="#d97706" stroke-width="1.8"/>\n  <text x="262" y="136" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#92400e">2. İBADET VE AHLAK</text>\n  <text x="262" y="156" text-anchor="middle" font-size="9" fill="#334155">• Namaz, oruç, zekât, hac</text>\n  <text x="262" y="172" text-anchor="middle" font-size="9" fill="#334155">• Doğruluk, sabır, ihsan</text>\n  <text x="262" y="188" text-anchor="middle" font-size="9" fill="#334155">• Adalet ve merhamet</text>\n  <rect x="352" y="115" width="152" height="105" rx="8" fill="#fae8ff" stroke="#9333ea" stroke-width="1.8"/>\n  <text x="428" y="136" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#6b21a8">3. MUÂMELÂT</text>\n  <text x="428" y="156" text-anchor="middle" font-size="9" fill="#334155">• Aile ve miras hukuku</text>\n  <text x="428" y="172" text-anchor="middle" font-size="9" fill="#334155">• Ticaret ve sözleşme ahlakı</text>\n  <text x="428" y="188" text-anchor="middle" font-size="9" fill="#334155">• Toplumsal hak ve görevler</text>\n  <rect x="518" y="115" width="162" height="105" rx="8" fill="#fee2e2" stroke="#dc2626" stroke-width="1.8"/>\n  <text x="599" y="136" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#991b1b">4. KISSALAR VE KÂİNAT</text>\n  <text x="599" y="156" text-anchor="middle" font-size="9" fill="#334155">• Peygamberlerin tevhid</text>\n  <text x="599" y="172" text-anchor="middle" font-size="9" fill="#334155">mücadelesi (ibret/öğüt)</text>\n  <text x="599" y="188" text-anchor="middle" font-size="9" fill="#334155">• Kevnî ayetler ve tefekkür</text>\n</svg>', '<svg viewBox="0 0 700 230" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="230" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">KUR\'AN\'DA ALLAH TEÂLÂ\'YI TANITAN ÜÇ TEMEL VAHİY METNİ</text>\n  <rect x="20" y="46" width="210" height="164" rx="10" fill="#dbeafe" stroke="#2563eb" stroke-width="1.8"/>\n  <text x="125" y="68" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#1e40af">1. İHLÂS SURESİ (1-4)</text>\n  <text x="125" y="88" text-anchor="middle" font-size="10" font-weight="bold" fill="#0f172a">قُلْ هُوَ اللّٰهُ أَحَدٌ · اللّٰهُ الصَّمَدُ</text>\n  <text x="125" y="110" text-anchor="middle" font-size="9" fill="#334155">• el-Ehad: Zatında tek ve eşsiz.</text>\n  <text x="125" y="128" text-anchor="middle" font-size="9" fill="#334155">• es-Samed: Her şeyin O\'na muhtaç</text>\n  <text x="125" y="144" text-anchor="middle" font-size="9" fill="#334155">olduğu, kendisi muhtaç olmayan.</text>\n  <text x="125" y="164" text-anchor="middle" font-size="9" font-weight="bold" fill="#1d4ed8">• Doğurmamış, doğurulmamış ve</text>\n  <text x="125" y="180" text-anchor="middle" font-size="9" font-weight="bold" fill="#1d4ed8">hiçbir dengi olmayandır.</text>\n  <rect x="245" y="46" width="210" height="164" rx="10" fill="#fef3c7" stroke="#d97706" stroke-width="1.8"/>\n  <text x="350" y="68" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#92400e">2. ÂYETÜ\'L-KÜRSÎ (Bakara 255)</text>\n  <text x="350" y="88" text-anchor="middle" font-size="10" font-weight="bold" fill="#0f172a">اللّٰهُ لَا إِلٰهَ إِلَّا هُوَ الْحَيُّ الْقَيُّومُ</text>\n  <text x="350" y="110" text-anchor="middle" font-size="9" fill="#334155">• el-Hayy: Ezelî ve ebedî diri olan.</text>\n  <text x="350" y="128" text-anchor="middle" font-size="9" fill="#334155">• el-Kayyûm: Kâinatı ayakta tutan.</text>\n  <text x="350" y="146" text-anchor="middle" font-size="9" fill="#334155">• Uyuklama (سِنَةٌ) ve uykudan münezzeh.</text>\n  <text x="350" y="164" text-anchor="middle" font-size="9" font-weight="bold" fill="#b45309">• Kürsîsi (ilmi ve hükümranlığı)</text>\n  <text x="350" y="180" text-anchor="middle" font-size="9" font-weight="bold" fill="#b45309">gökleri ve yeri kuşatmıştır.</text>\n  <rect x="470" y="46" width="210" height="164" rx="10" fill="#dcfce7" stroke="#16a34a" stroke-width="1.8"/>\n  <text x="575" y="68" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#166534">3. HAŞR SURESİ (22-24)</text>\n  <text x="575" y="88" text-anchor="middle" font-size="10" font-weight="bold" fill="#0f172a">هُوَ اللّٰهُ الَّذِي لَا إِلٰهَ إِلَّا هُوَ</text>\n  <text x="575" y="110" text-anchor="middle" font-size="9" fill="#334155">• Gaybı ve görünen âlemi bilen.</text>\n  <text x="575" y="128" text-anchor="middle" font-size="9" fill="#334155">• Melik, Kuddûs, Selâm, Mü\'min,</text>\n  <text x="575" y="144" text-anchor="middle" font-size="9" fill="#334155">Müheymin, Azîz, Cebbâr, Mütekebbir.</text>\n  <text x="575" y="164" text-anchor="middle" font-size="9" font-weight="bold" fill="#15803d">• Hâlık, Bâri\', Musavvir; göklerde</text>\n  <text x="575" y="180" text-anchor="middle" font-size="9" font-weight="bold" fill="#15803d">ve yerde her şey O\'nu tesbih eder.</text>\n</svg>', '<svg viewBox="0 0 700 230" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="230" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">AYET TAHLİLİNDE FARKLI MÜFESSİRLERİN YÖNTEM MUKAYESESİ</text>\n  <rect x="20" y="46" width="210" height="164" rx="10" fill="#dbeafe" stroke="#2563eb" stroke-width="1.8"/>\n  <text x="125" y="68" text-anchor="middle" font-size="11" font-weight="bold" fill="#1e40af">1. RİVAYET VE NÜZUL ODAKLI</text>\n  <text x="125" y="88" text-anchor="middle" font-size="9.5" font-weight="bold" fill="#1d4ed8">Taberî · İbn Kesîr · Vâhidî</text>\n  <rect x="32" y="98" width="186" height="98" rx="6" fill="#ffffff" stroke="#93c5fd"/>\n  <text x="125" y="118" text-anchor="middle" font-size="9" fill="#334155">• Ayeti diğer ayetlerle, hadislerle</text>\n  <text x="125" y="134" text-anchor="middle" font-size="9" fill="#334155">ve sahabe/tâbiîn sözleriyle açıklar.</text>\n  <text x="125" y="152" text-anchor="middle" font-size="9" fill="#334155">• Vâhidî (Esbâbü\'n-Nüzûl): İhlâs</text>\n  <text x="125" y="168" text-anchor="middle" font-size="9" fill="#334155">suresinin iniş sebebini nakleder.</text>\n  <rect x="245" y="46" width="210" height="164" rx="10" fill="#dcfce7" stroke="#16a34a" stroke-width="1.8"/>\n  <text x="350" y="68" text-anchor="middle" font-size="11" font-weight="bold" fill="#166534">2. DİRAYET VE BELAGAT ODAKLI</text>\n  <text x="350" y="88" text-anchor="middle" font-size="9.5" font-weight="bold" fill="#15803d">Râzî · Ebüssuûd · Elmalılı</text>\n  <rect x="257" y="98" width="186" height="98" rx="6" fill="#ffffff" stroke="#86efac"/>\n  <text x="350" y="118" text-anchor="middle" font-size="9" fill="#334155">• Rivayetlerin yanında dil, belagat,</text>\n  <text x="350" y="134" text-anchor="middle" font-size="9" fill="#334155">kelam ve akli istidlal kullanır.</text>\n  <text x="350" y="152" text-anchor="middle" font-size="9" fill="#334155">• Ebüssuûd Efendi (İrşâdü\'l-Aklis-</text>\n  <text x="350" y="168" text-anchor="middle" font-size="9" fill="#334155">Selîm): Belagat ve nazım inceliği.</text>\n  <rect x="470" y="46" width="210" height="164" rx="10" fill="#fae8ff" stroke="#9333ea" stroke-width="1.8"/>\n  <text x="575" y="68" text-anchor="middle" font-size="11" font-weight="bold" fill="#6b21a8">3. İŞÂRÎ VE AHLAKİ ODAKLI</text>\n  <text x="575" y="88" text-anchor="middle" font-size="9.5" font-weight="bold" fill="#7e22ce">İsmail Hakkı Bursevî</text>\n  <rect x="482" y="98" width="186" height="98" rx="6" fill="#ffffff" stroke="#e9d5ff"/>\n  <text x="575" y="118" text-anchor="middle" font-size="9" fill="#334155">• Zahirî anlamı koruyarak ayetin</text>\n  <text x="575" y="134" text-anchor="middle" font-size="9" fill="#334155">kalbî ve ahlaki işaretlerini açıklar.</text>\n  <text x="575" y="152" text-anchor="middle" font-size="9" fill="#334155">• Bursevî (Rûhu\'l-Beyân): Marifet,</text>\n  <text x="575" y="168" text-anchor="middle" font-size="9" fill="#334155">zikir, hikmet ve edep boyutu.</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get('bolumler', [])):
        if i < len(SVGS):
            b['gorsel'] = SVGS[i]
